import React, { useEffect } from 'react';

// ==========================================
// 1. Create a Person class
// ==========================================
class Person {
  constructor(name, age) {
    this.name = name;
    this.age = age;
  }

  // Method introduce()
  introduce() {
    return `Hello, my name is ${this.name} and I am ${this.age} years old.`;
  }
}

// ==========================================
// 2. Create a Student class that extends Person
// ==========================================
class Student extends Person {
  constructor(name, age, scores = []) {
    super(name, age);
    this.scores = scores; // Additional property: scores (array of grades)
  }

  // Method: Calculate average score
  calculateAverage() {
    if (this.scores.length === 0) return 0;
    const total = this.scores.reduce((sum, score) => sum + score, 0);
    return (total / this.scores.length).toFixed(2);
  }

  // Method: Display full student information
  displayFullInfo() {
    console.log("=== FULL STUDENT INFO ===");
    console.log(this.introduce());
    console.log(`Scores: [${this.scores.join(', ')}]`);
    console.log(`Average score: ${this.calculateAverage()}`);
  }
}

// ==========================================
// 3. Use Rest Parameter
// ==========================================
// Function accepts multiple score values and returns them as an array
const createScores = (...scores) => {
  return scores;
};

// ==========================================
// 4. Use Destructuring
// ==========================================
const extractStudentDetails = (studentObj) => {
  // Extract name and age from a student object
  const { name, age } = studentObj;
  console.log(`Extracted Name: ${name}, Extracted Age: ${age}`);
};

// ==========================================
// MAIN REACT COMPONENT
// ==========================================
export default function App() {
  useEffect(() => {
    console.clear();
    console.log("================ ASSIGNMENT DEMO RUN ================\n");

    // --- REQUIREMENT 1, 2, 3 ---
    const initialScores = createScores(8, 9, 10);
    const student = new Student("Alex", 20, initialScores);

    console.log("--- 1 & 2. Person & Student Class ---");
    student.displayFullInfo();

    console.log("\n--- 3. Rest Parameter ---");
    console.log("Created Scores Array:", initialScores);

    // --- REQUIREMENT 4: Destructuring ---
    console.log("\n--- 4. Destructuring ---");
    extractStudentDetails(student);

    // --- REQUIREMENT 5: Spread Operator ---
    console.log("\n--- 5. Spread Operator ---");
    const newScores = [7, 8.5];
    student.scores = [...student.scores, ...newScores];
    console.log("Merged Scores List:", student.scores);

    // --- REQUIREMENT 6: Array Methods ---
    console.log("\n--- 6. Array Methods ---");

    // filter(): filter passing scores
    const passingScores = student.scores.filter(score => score >= 5);
    console.log("filter() - Passing scores:", passingScores);

    // map(): process score data
    const processedScores = student.scores.map(score => `${score} pts`);
    console.log("map() - Processed scores:", processedScores);

    // reduce(): calculate total or average score
    const totalScore = student.scores.reduce((sum, score) => sum + score, 0);
    console.log("reduce() - Total score:", totalScore);
    console.log("reduce() - Calculated average:", (totalScore / student.scores.length).toFixed(2));

    // --- REQUIREMENT 7: Promise ---
    console.log("\n--- 7. Promise ---");
    const evaluateAcademicPerformance = (avg) => {
      return new Promise((resolve) => {
        setTimeout(() => {
          if (avg >= 8) {
            resolve("Excellent Student");
          } else {
            resolve("Need Improvement");
          }
        }, 500);
      });
    };

    const currentAvg = parseFloat(student.calculateAverage());
    evaluateAcademicPerformance(currentAvg).then((evaluationResult) => {
      console.log(`Academic Evaluation Result (avg = ${currentAvg}): "${evaluationResult}"`);
      console.log("\n====================================================");
    });

  }, []);


}
